-- relations that become NOT NULL *_pk: every old value must point at a row, or the copy below would stop on a bare
-- "null value in column …" — named here with their counts and up to 5 values
DO $$
DECLARE
  c bigint;
  s text;
  found text;
BEGIN
  SELECT count(*) INTO c FROM job o WHERE NOT EXISTS (SELECT 1 FROM model p WHERE p.model_id = o.product_model_id);
  IF c > 0 THEN
    SELECT string_agg(v, ', ') INTO s FROM (
      SELECT DISTINCT coalesce(o.product_model_id::text, 'NULL') AS v FROM job o WHERE NOT EXISTS (SELECT 1 FROM model p WHERE p.model_id = o.product_model_id) ORDER BY 1 LIMIT 5) x;
    found := concat_ws('; ', found, format('%s: %s (%s)', 'job.product_model_id', c, s));
  END IF;
  SELECT count(*) INTO c FROM app_user_tour o WHERE NOT EXISTS (SELECT 1 FROM app_user p WHERE p.user_id = o.user_id);
  IF c > 0 THEN
    SELECT string_agg(v, ', ') INTO s FROM (
      SELECT DISTINCT coalesce(o.user_id::text, 'NULL') AS v FROM app_user_tour o WHERE NOT EXISTS (SELECT 1 FROM app_user p WHERE p.user_id = o.user_id) ORDER BY 1 LIMIT 5) x;
    found := concat_ws('; ', found, format('%s: %s (%s)', 'app_user_tour.user_id', c, s));
  END IF;
