  SELECT count(*) INTO a FROM sale_out_hd o JOIN sale_out_hd__new n ON n.id = o.id WHERE n.record_status IS NOT NULL AND n.record_status IS DISTINCT FROM o.record_status;
  IF a > 0 THEN RAISE EXCEPTION 'sale_out_hd.record_status → record_status: % rows name another record_status than before', a; END IF;
  SELECT count(*) INTO a FROM sale_out_hd o JOIN sale_out_hd__new n ON n.id = o.id WHERE n.status_changed_by_app_user_pk IS NOT NULL AND n.status_changed_by_app_user_pk IS DISTINCT FROM o.status_changed_by;
  IF a > 0 THEN RAISE EXCEPTION 'sale_out_hd.status_changed_by → status_changed_by_app_user_pk: % rows name another app_user than before', a; END IF;
  SELECT count(*) INTO a FROM sale_out_hd o JOIN sale_out_hd__new n ON n.id = o.id WHERE n.document_profile_pk IS NOT NULL AND n.document_profile_pk IS DISTINCT FROM o.document_profile_id;
  IF a > 0 THEN RAISE EXCEPTION 'sale_out_hd.document_profile_id → document_profile_pk: % rows name another document_profile than before', a; END IF;
  SELECT count(*) INTO a FROM shipping_profile o JOIN shipping_profile__new n ON n.id = o.id WHERE n.deleted_by_app_user_pk IS NOT NULL AND n.deleted_by_app_user_pk IS DISTINCT FROM o.deleted_by;
