  IF a > 0 THEN RAISE EXCEPTION 'symptom.status_changed_by → status_changed_by_app_user_pk: % rows name another app_user than before', a; END IF;
  SELECT count(*) INTO a FROM track_doc_ticket o JOIN track_doc_ticket__new n ON n.id = o.id JOIN job__new p ON p.pk = n.job_pk WHERE p.job_no IS DISTINCT FROM o.job_no;
  IF a > 0 THEN RAISE EXCEPTION 'track_doc_ticket.job_no → job_pk: % rows name another job than before', a; END IF;
  SELECT count(*) INTO a FROM track_doc_ticket o JOIN track_doc_ticket__new n ON n.id = o.id JOIN quotation_hd__new p ON p.pk = n.quotation_hd_pk WHERE p.quotation_no IS DISTINCT FROM o.ref;
