-- === 7. The swap, and the new names ==========================================================================
-- CHECKs (verbatim: NOT VALID stays NOT VALID — ck_inventory_dt_qty), grants and FORCE RLS as the old table had
-- them: copied from the live table, so a database that differs from the migrations (0031 adds a check only where no row
-- breaks it) keeps exactly what it had
DO $$
DECLARE
  t text;
  g record;
BEGIN
  FOREACH t IN ARRAY ARRAY['app_back_up_db_log', 'app_config', 'app_user', 'app_user_tour', 'approve_status', 'audit_log', 'category', 'color', 'condition', 'customer', 'document_attach', 'document_profile', 'idempotency_key', 'inventory_dt', 'inventory_hd', 'inventory_type', 'job', 'job_call_log', 'job_close_temp', 'job_create_temp', 'job_log', 'job_order_spare_part_log', 'job_order_spare_part_status', 'job_return_dt', 'job_return_hd', 'job_send_forward_dt', 'job_service_code', 'job_status', 'job_symptom', 'job_type', 'manufacturer', 'model', 'model_color', 'model_part', 'model_tier', 'mt_city', 'mt_district', 'mt_sub_district', 'product', 'product_model', 'product_none_serial', 'product_serial', 'product_type', 'quotation_dt', 'quotation_hd', 'quotation_status', 'quotation_temp', 'record_status', 'running_no', 'sale_in_dt', 'sale_in_hd', 'sale_out_dt', 'sale_out_hd', 'service_cost', 'shipping_profile', 'store_location', 'symptom', 'temp_model', 'temp_spare_part', 'track_block', 'track_doc_ticket', 'track_event', 'track_otp', 'track_rate', 'track_session', 'track_ticket'] LOOP
    FOR g IN SELECT conname, pg_get_constraintdef(oid) AS def FROM pg_constraint
              WHERE conrelid = format('public.%I', t)::regclass AND contype = 'c' LOOP
      EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I %s', t || '__new', g.conname, g.def);
    END LOOP;
    FOR g IN SELECT DISTINCT grantee FROM information_schema.role_table_grants
              WHERE table_schema = 'public' AND table_name = t || '__new' AND grantee <> current_user LOOP
      EXECUTE format('REVOKE ALL ON %I FROM %s', t || '__new', CASE WHEN g.grantee = 'PUBLIC' THEN 'PUBLIC' ELSE quote_ident(g.grantee) END);
    END LOOP;
    FOR g IN SELECT grantee, privilege_type FROM information_schema.role_table_grants
              WHERE table_schema = 'public' AND table_name = t AND grantee <> current_user LOOP
      EXECUTE format('GRANT %s ON %I TO %s', g.privilege_type, t || '__new', CASE WHEN g.grantee = 'PUBLIC' THEN 'PUBLIC' ELSE quote_ident(g.grantee) END);
    END LOOP;
    IF (SELECT relforcerowsecurity FROM pg_class WHERE oid = format('public.%I', t)::regclass) THEN
      EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t || '__new');
    END IF;
  END LOOP;
END $$;
