-- === 9. Triggers, functions, row level security, comments, the legacy boundary ===============================
-- the columns every status change writes are ignored by name: status_changed_by is status_changed_by_app_user_pk now
CREATE OR REPLACE FUNCTION public.bump_row_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  -- TG_ARGV is NULL when the trigger has no arguments
  ignored text[] := coalesce(TG_ARGV, '{}') || ARRAY['row_version', 'status_changed_at', 'status_changed_by_app_user_pk'];
BEGIN
  IF (to_jsonb(NEW) - ignored) IS DISTINCT FROM (to_jsonb(OLD) - ignored) THEN
    NEW.row_version := OLD.row_version + 1;
  ELSIF NEW.row_version IS DISTINCT FROM OLD.row_version AND NEW.row_version > OLD.row_version THEN
    NEW.row_version := OLD.row_version + 1; -- asked for: another table's change is an edit of this row
  ELSE
    NEW.row_version := OLD.row_version; -- only ignored columns changed (or nothing): not an edit
  END IF;
  RETURN NEW;
END $function$
;
--> statement-breakpoint
-- row_hash: sha256 of the row as written (every column but row_hash), set BEFORE INSERT — what a later change to a
-- row would contradict. Each row on its own, no chain: a chain (each hash over the previous) would serialize every
-- write of the system on one row lock.
CREATE FUNCTION log_row_hash() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.row_hash := sha256(convert_to((to_jsonb(NEW) - 'row_hash')::text, 'UTF8'));
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE FUNCTION log_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME;
END $$;
--> statement-breakpoint
-- the copied rows: hashed now (before the append-only trigger exists) — the hash proves "unchanged since drizzle/0006"
UPDATE audit_log SET row_hash = sha256(convert_to((to_jsonb(audit_log) - 'row_hash')::text, 'UTF8'));
--> statement-breakpoint
CREATE TRIGGER trg_audit_log_row_hash BEFORE INSERT ON audit_log FOR EACH ROW EXECUTE FUNCTION log_row_hash();
--> statement-breakpoint
CREATE TRIGGER trg_audit_log_no_truncate BEFORE TRUNCATE ON audit_log FOR EACH STATEMENT EXECUTE FUNCTION audit_log_readonly();
--> statement-breakpoint
CREATE TRIGGER trg_audit_log_readonly BEFORE DELETE OR UPDATE ON audit_log FOR EACH ROW EXECUTE FUNCTION audit_log_readonly();
--> statement-breakpoint
