-- sign-ins, refusals, role / permission / status changes, exports and prints (owner 2026-10-30, round 3)
CREATE TABLE security_log (
  pk bigint GENERATED ALWAYS AS IDENTITY,
  id uuid NOT NULL DEFAULT uuid_generate_v7(),
  at timestamp without time zone NOT NULL, -- as audit_log.at: Thai wall clock (ADR 0001), written by the app
  event varchar(20) NOT NULL,
  result varchar(10) NOT NULL,
  actor_pk bigint,
  actor_name varchar(100),
  actor_email varchar(100),
  actor_role varchar(50),
  actor_department varchar(100),
  ip inet,
  user_agent text,
  session_id text,
  request_id text,
  module varchar(50),
  permission text,
  entity varchar(50),
  entity_id uuid,
  entity_no text,
  detail jsonb,
  row_hash bytea,
  CONSTRAINT security_log_pkey PRIMARY KEY (pk),
  CONSTRAINT ck_security_log_event CHECK (event IN ('LOGIN', 'LOGIN_FAILED', 'LOGOUT', 'DENIED', 'ROLE_CHANGE', 'PERMISSION_CHANGE', 'USER_STATUS', 'EXPORT', 'PRINT')),
  CONSTRAINT ck_security_log_result CHECK (result IN ('OK', 'DENIED', 'FAILED')),
  CONSTRAINT fk_security_log_actor_pk FOREIGN KEY (actor_pk) REFERENCES app_user (pk) ON DELETE RESTRICT
);
--> statement-breakpoint
CREATE UNIQUE INDEX ux_security_log_id ON security_log (id);
--> statement-breakpoint
CREATE INDEX ix_security_log_at ON security_log (at);
--> statement-breakpoint
CREATE INDEX ix_security_log_actor ON security_log (actor_pk, at);
--> statement-breakpoint
CREATE INDEX ix_security_log_event ON security_log (event, at);
--> statement-breakpoint
ALTER TABLE security_log ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    EXECUTE 'REVOKE ALL ON TABLE security_log FROM anon';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    EXECUTE 'REVOKE ALL ON TABLE security_log FROM authenticated';
  END IF;
END $$;
--> statement-breakpoint
CREATE TRIGGER trg_security_log_row_hash BEFORE INSERT ON security_log FOR EACH ROW EXECUTE FUNCTION log_row_hash();
--> statement-breakpoint
CREATE TRIGGER trg_security_log_readonly BEFORE DELETE OR UPDATE ON security_log FOR EACH ROW EXECUTE FUNCTION log_append_only();
--> statement-breakpoint
CREATE TRIGGER trg_security_log_no_truncate BEFORE TRUNCATE ON security_log FOR EACH STATEMENT EXECUTE FUNCTION log_append_only();
--> statement-breakpoint
COMMENT ON TABLE security_log IS 'Security events: sign-in / failed sign-in / sign-out, refusals, role / permission / user status changes, exports, prints — actor as at the time. Append-only. LOGIN rows written before drizzle/0006 stay in audit_log. retention: forever for now — owner to decide (suggested: audit forever, security_log 1 year under PDPA).';
