-- rows with pk <= max_pk came from the legacy system: the app locks their money / quantity fields (owner 2026-10-30)
CREATE TABLE legacy_boundary (
  pk bigint GENERATED ALWAYS AS IDENTITY,
  id uuid NOT NULL DEFAULT uuid_generate_v7(),
  table_name varchar(63) NOT NULL,
  max_pk bigint NOT NULL,
  loaded_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT legacy_boundary_pkey PRIMARY KEY (pk)
);
